"use client";
import { OperationsWorkspaceShell, type OperationsWorkspaceOptions } from "../operations-workspace-shell-01";
import { ListPagination } from "@ui/list-pagination";
import { useEffect, useMemo, useState, type ComponentPropsWithoutRef } from "react";
import AiAudioIcon from "@hugeicons/core-free-icons/AiAudioIcon";
import { HugeiconsIcon } from "@hugeicons/react";
import { Empty, EmptyDescription } from "@ui/empty";
import { Badge } from "@ui/badge";
import { Button } from "@ui/button";
import { DropdownContent, DropdownMenu, DropdownTrigger } from "@ui/dropdown";
import { Input } from "@ui/input";
import { MenuItem } from "@ui/menu-item";
import { PageBody, PageContent } from "@ui/page-layout";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
export type InspectionReportPriority = "critical" | "normal";
export interface InspectionReportItem {
    id: string;
    name: string;
    environment: string;
    location: string;
    priority: InspectionReportPriority;
    issue?: string;
    freshness: "latest" | "expired";
    generatedAt: string;
    duration: string;
}
export interface InspectionReportListProps extends Omit<ComponentPropsWithoutRef<"div">, "children"> {
    workspace?: OperationsWorkspaceOptions;
    reports?: readonly InspectionReportItem[];
    onRefresh?: () => void;
    onViewReport?: (report: InspectionReportItem) => void;
}
export const defaultInspectionReportItems = [
    { id: "report-b-critical", name: "生产环境 B 的巡检报告", environment: "生产环境 B", location: "生产 · 成都机房", priority: "critical", issue: "网络冗余丢失", freshness: "latest", generatedAt: "2026/7/30 19:00:09", duration: "59s" },
    { id: "report-a-critical", name: "生产环境 A 的巡检报告", environment: "生产环境 A", location: "生产 · 上海一号机房", priority: "critical", issue: "4项脚本执行失败", freshness: "latest", generatedAt: "2026/7/30 19:00:09", duration: "59s" },
    { id: "report-b-normal", name: "生产环境 B 的巡检报告", environment: "生产环境 B", location: "生产 · 成都机房", priority: "normal", freshness: "expired", generatedAt: "2026/7/30 19:00:09", duration: "59s" },
    { id: "report-c-critical", name: "生产环境 C 的巡检报告", environment: "生产环境 C", location: "生产 · 北京机房", priority: "critical", issue: "核心服务存在高可用风险", freshness: "latest", generatedAt: "2026/7/30 18:30:24", duration: "1m 12s" },
    { id: "report-a-normal", name: "生产环境 A 的巡检报告", environment: "生产环境 A", location: "生产 · 上海一号机房", priority: "normal", freshness: "latest", generatedAt: "2026/7/30 18:00:10", duration: "48s" },
    { id: "report-dr-warning", name: "容灾环境的巡检报告", environment: "容灾环境", location: "容灾 · 深圳机房", priority: "critical", issue: "备份链路延迟超过阈值", freshness: "expired", generatedAt: "2026/7/30 17:15:43", duration: "1m 06s" },
    { id: "report-staging", name: "预发布环境的巡检报告", environment: "预发布环境", location: "测试 · 杭州机房", priority: "normal", freshness: "latest", generatedAt: "2026/7/30 16:30:12", duration: "43s" },
    { id: "report-database", name: "数据库集群的巡检报告", environment: "生产环境 C", location: "生产 · 北京机房", priority: "critical", issue: "副本延迟持续升高", freshness: "expired", generatedAt: "2026/7/30 15:45:08", duration: "1m 24s" },
] as const satisfies readonly InspectionReportItem[];
function ReportRow({ report, onView }: {
    report: InspectionReportItem;
    onView?: (report: InspectionReportItem) => void;
}) { const Report = useIcon("check-square"); const Check = useIcon("check"); const More = useIcon("ellipsis"); return <div className="grid min-w-[960px] grid-cols-[minmax(280px,1.1fr)_minmax(210px,.7fr)_minmax(420px,1fr)_auto] items-center border-b-hairline border-border px-3 py-2 last:border-b-0"><div className="flex min-w-0 items-center gap-2"><Report className="size-5 shrink-0 text-fg-default" strokeWidth={1.5}/><p className="truncate text-body font-medium text-fg-default">{report.name}</p><span className="truncate text-body text-fg-muted">{report.location}</span></div><div className="flex min-w-0 items-center gap-2">{report.priority === "critical" ? <Badge status="danger" size="sm" variant="strong">严重 · P1</Badge> : <Badge status="success" size="sm" variant="strong">正常</Badge>} {report.issue && <span className="truncate text-body text-fg-default">{report.issue}</span>}</div><div className="flex items-center gap-5 text-body"><span className="flex items-center gap-1.5 whitespace-nowrap"><span aria-label="已生成" className="grid size-5 shrink-0 place-items-center"><span className="grid size-4 place-items-center rounded-sm bg-success-surface text-fg-success"><Check size={14} strokeWidth={2}/></span></span>已生成 <span className="text-label text-fg-muted">{report.duration}</span></span><span className="flex items-center gap-1.5 whitespace-nowrap"><span aria-label={report.freshness === "latest" ? "最新报告" : "报告已过期"} className="grid size-5 shrink-0 place-items-center"><span className={cn("size-2 rounded-full", report.freshness === "latest" ? "bg-fg-success" : "bg-fg-warning")}/></span>{report.freshness === "latest" ? "最新报告" : "报告已过期"}</span><span className="whitespace-nowrap text-label text-fg-muted">生成于 {report.generatedAt}</span></div><div className="flex items-center gap-1"><Button aria-label={`查看 ${report.name}`} iconOnly onClick={() => onView?.(report)} size="md" type="button" variant="ghost"><HugeiconsIcon aria-hidden="true" icon={AiAudioIcon} size={16} strokeWidth={1.5}/></Button><DropdownMenu><DropdownTrigger render={<Button aria-label={`${report.name} 更多操作`} iconOnly size="md" type="button" variant="ghost"><More size={16} strokeWidth={1.5}/></Button>}/><DropdownContent align="end"><MenuItem index={0} label="查看报告" onSelect={() => onView?.(report)}/><MenuItem index={1} label="下载报告" onSelect={() => undefined}/></DropdownContent></DropdownMenu></div></div>; }
/** A ZAIops inspection report list with the shared operations navigation shell. */
export function InspectionReportList({ workspace, reports = defaultInspectionReportItems, className, onRefresh, onViewReport, ...props }: InspectionReportListProps) {
    const [query, setQuery] = useState("");
    const [priority, setPriority] = useState<InspectionReportPriority | "all">("all");
    const [environment, setEnvironment] = useState("all");
    const [page, setPage] = useState(0);
    const [pageSize, setPageSize] = useState(5);
    const Search = useIcon("search");
    const Check = useIcon("check-square");
    useEffect(() => setPage(0), [environment, pageSize, priority, query]);
    const visibleReports = useMemo(() => reports.filter((report) => (priority === "all" || report.priority === priority) && (environment === "all" || report.environment === environment) && `${report.name} ${report.location} ${report.issue ?? ""}`.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())), [environment, priority, query, reports]);
    useEffect(() => setPage(current => Math.min(current, Math.max(0, Math.ceil(visibleReports.length / pageSize) - 1))), [visibleReports.length, pageSize]);
    const currentPage = Math.min(page, Math.max(0, Math.ceil(visibleReports.length / pageSize) - 1));
    const pagedReports = visibleReports.slice(currentPage * pageSize, (currentPage + 1) * pageSize);
    const environments = [...new Set(reports.map((report) => report.environment))];
    return <OperationsWorkspaceShell workspace={workspace} activeNavigation="reports" title="巡检报告" icon={Check} className={cn("min-h-[42rem]", className)} {...props}><PageContent><PageBody className="max-w-[101.25rem] p-3"><section className="overflow-hidden rounded-xl border-hairline border-border bg-surface-floating"><div className="flex flex-wrap items-center gap-2 border-b-hairline border-border px-3 py-2"><label className="relative min-w-56 flex-1 lg:max-w-[28rem]"><span className="sr-only">搜索巡检报告</span><Search className="pointer-events-none absolute left-2 top-1/2 size-4 -translate-y-1/2 text-fg-subtle"/><Input className="pl-8" onChange={(event) => setQuery(event.target.value)} placeholder="搜索" value={query}/></label><DropdownMenu><DropdownTrigger render={<Button size="md" type="button" variant="tertiary">处置优先级</Button>}/><DropdownContent>{(["all", "critical", "normal"] as const).map((value, index) => <MenuItem checked={priority === value} index={index} key={value} label={value === "all" ? "全部优先级" : value === "critical" ? "严重 · P1" : "正常"} onSelect={() => setPriority(value)}/>)}</DropdownContent></DropdownMenu><DropdownMenu><DropdownTrigger render={<Button size="md" type="button" variant="tertiary">{environment === "all" ? "全部环境" : environment}</Button>}/><DropdownContent><MenuItem checked={environment === "all"} index={0} label="全部环境" onSelect={() => setEnvironment("all")}/>{environments.map((value, index) => <MenuItem checked={environment === value} index={index + 1} key={value} label={value} onSelect={() => setEnvironment(value)}/>)}</DropdownContent></DropdownMenu><Button className="ms-auto" onClick={onRefresh} size="md" type="button" variant="neutral">刷新</Button></div><div className="overflow-x-auto" aria-label="巡检报告列表">{pagedReports.map((report) => <ReportRow key={report.id} onView={onViewReport} report={report}/>)}{!visibleReports.length && <Empty scope="section" reason={query.trim() || priority !== "all" || environment !== "all" ? "no-results" : "no-data"}><EmptyDescription>{query.trim() || priority !== "all" || environment !== "all" ? "未找到符合条件的巡检报告。" : "暂无巡检报告。"}</EmptyDescription></Empty>}</div><ListPagination onPageChange={setPage} onPageSizeChange={(nextPageSize) => { setPage(0); setPageSize(nextPageSize); }} page={currentPage} pageSize={pageSize} total={visibleReports.length}/></section></PageBody></PageContent></OperationsWorkspaceShell>;
}
